import React, { useEffect, useState } from 'react';
import toast from 'react-hot-toast';
import { adminAPI } from '../services/api';

export default function AdminPage() {
  const [reports, setReports] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchReports = () => {
    setLoading(true);
    adminAPI.getPending()
      .then(({ data }) => setReports(data))
      .catch(() => toast.error('Failed to load reports'))
      .finally(() => setLoading(false));
  };

  useEffect(() => { fetchReports(); }, []);

  const handleConfirm = async (id) => {
    try {
      await adminAPI.confirmReport(id);
      toast.success('Report confirmed — idea flagged 🚩');
      fetchReports();
    } catch (err) { toast.error(err.response?.data?.message || 'Failed'); }
  };

  const handleDismiss = async (id) => {
    try {
      await adminAPI.dismissReport(id);
      toast.success('Report dismissed');
      fetchReports();
    } catch (err) { toast.error(err.response?.data?.message || 'Failed'); }
  };

  return (
    <div className="page-wrapper" style={{ paddingTop: 40, paddingBottom: 64 }}>
      <h1 style={{ fontFamily:'var(--font-display)', fontSize:'2rem', marginBottom: 8 }}>
        🛡️ <span className="gradient-text">Admin Panel</span>
      </h1>
      <p style={{ color:'var(--text-secondary)', marginBottom: 32 }}>Manage plagiarism reports and platform moderation</p>

      {loading ? (
        <div className="page-loader"><div className="spinner" /></div>
      ) : reports.length === 0 ? (
        <div style={{ textAlign:'center', padding: 60, color:'var(--text-muted)' }}>
          <p style={{ fontSize:'2rem', marginBottom: 12 }}>✅</p>
          <p>No pending reports — the platform is clean!</p>
        </div>
      ) : (
        <div style={{ display:'flex', flexDirection:'column', gap: 16 }}>
          {reports.map((item) => (
            <div key={item.report.id} className="glass-card" style={{ padding: 24 }}>
              <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap: 16, marginBottom: 16 }}>
                {/* Reported idea */}
                <div style={{ padding: 16, background:'rgba(244,63,94,.06)', border:'1px solid rgba(244,63,94,.2)', borderRadius: 10 }}>
                  <p style={{ fontSize: 11, color:'var(--accent-danger)', fontWeight: 700, textTransform:'uppercase', marginBottom: 6 }}>🚨 Reported Idea</p>
                  <p style={{ fontWeight: 600, marginBottom: 4 }}>{item.reportedIdea?.title}</p>
                  <p style={{ fontSize: 13, color:'var(--text-muted)' }}>by {item.reportedIdea?.authorName}</p>
                </div>
                {/* Original idea */}
                <div style={{ padding: 16, background:'rgba(16,185,129,.06)', border:'1px solid rgba(16,185,129,.2)', borderRadius: 10 }}>
                  <p style={{ fontSize: 11, color:'var(--accent-success)', fontWeight: 700, textTransform:'uppercase', marginBottom: 6 }}>✅ Original Idea</p>
                  <p style={{ fontWeight: 600, marginBottom: 4 }}>{item.originalIdea?.title}</p>
                  <p style={{ fontSize: 13, color:'var(--text-muted)' }}>by {item.originalIdea?.authorName}</p>
                </div>
              </div>
              <p style={{ fontSize: 13, color:'var(--text-secondary)', marginBottom: 16 }}>
                <strong>Reason:</strong> {item.report?.reason || 'No reason given'}
              </p>
              <div style={{ display:'flex', gap: 10 }}>
                <button className="btn-danger" onClick={() => handleConfirm(item.report.id)}>
                  🚩 Confirm Plagiarism
                </button>
                <button className="btn-secondary" onClick={() => handleDismiss(item.report.id)}>
                  ✕ Dismiss
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
